require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$total=(int)$pdo->query('SELECT COUNT(*) FROM solicitudes')->fetchColumn();$pendientes=(int)$pdo->query("SELECT COUNT(*) FROM solicitudes WHERE estado='Pendiente'")->fetchColumn();$proceso=(int)$pdo->query("SELECT COUNT(*) FROM reparaciones WHERE estado NOT IN ('Terminada')")->fetchColumn();$terminadas=(int)$pdo->query("SELECT COUNT(*) FROM reparaciones WHERE estado='Terminada'")->fetchColumn();$ingresos=(float)$pdo->query("SELECT COALESCE(SUM(monto),0) FROM pagos WHERE estado='Pagado'")->fetchColumn();$promedio=(float)$pdo->query('SELECT COALESCE(AVG(calificacion),0) FROM resenas')->fetchColumn();$consolas=$pdo->query('SELECT tipo_consola,COUNT(*) AS total FROM solicitudes GROUP BY tipo_consola ORDER BY total DESC')->fetchAll();$titulo_pagina='Reportes';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">ANÁLISIS DEL NEGOCIO</span><h1>Reportes</h1><p>Indicadores sencillos para presentar el desempeño de RetroFix.</p></div></div><div class="rejilla-metricas"><div class="metrica"><small>TOTAL SOLICITUDES</small><strong class="morado"><?= $total ?></strong></div><div class="metrica"><small>PENDIENTES</small><strong><?= $pendientes ?></strong></div><div class="metrica"><small>EN PROCESO</small><strong class="azul"><?= $proceso ?></strong></div><div class="metrica"><small>TERMINADAS</small><strong class="verde"><?= $terminadas ?></strong></div><div class="metrica"><small>PROMEDIO RESEÑAS</small><strong class="amarillo"><?= number_format($promedio,1) ?>/5</strong></div></div><div class="rejilla-dos"><section class="tarjeta"><h3>Ingresos acumulados</h3><div style="font:700 2.6rem 'Manrope'" class="texto-verde">$<?= number_format($ingresos,2) ?> <small>MXN</small></div><p>Solo pagos con estado Pagado.</p></section><section class="tarjeta"><h3>Consolas más solicitadas</h3><?php foreach($consolas as $c): ?><div class="fila-detalle"><span><?= escapar($c['tipo_consola']) ?></span><strong><?= $c['total'] ?> solicitudes</strong></div><?php endforeach; ?></section></div><?php require_once __DIR__.'/../includes/pie.php'; ?>



